#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""cornholio - a quiet Spotify client for the terminal.

One huge title glowing in a dark window, a slow sky behind it, and your
library one key away. Everything is drawn from text characters.

    cornholio                 start (logs in on first run)
    cornholio login           log in to the Spotify Web API again
    cornholio player-login    one-time setup for the audio player (Soloist or librespot)
    cornholio --demo          run with a fake library (no account needed)
    cornholio --help          this text

Safety: cornholio never deletes, unlikes, unfollows or removes anything from your
Spotify account. Only reading, playback control, adding and creating are on its
allow-list. Hiding, reordering and unliking (L) are stored locally in
~/.local/share/cornholio.

Built from parts in src/; this file is generated by build.sh.
"""

