# ── Colour themes ───────────────────────────────────────────────────────────
# Every colour on screen is one of these variables. `t` cycles themes and the
# whole palette cross-fades; add your own with a THEMES["name"] = _ui(...) line
# (and an AURORA line for its aurora).
#
#   bg      the near-black field          fg      the hero glow, primary text
#   dim     secondary text (labels)       faint   hints, quiet metadata
#   ghost   barely-there marks            accent  the lamp: cursor, now playing
#   accent2 planets, cold highlights      star    starlight
#   snow    flakes and drifts             sel     selection / raised plate
#   lift    a picked-up row               warn    soft warnings
#   body    penguin coats                 beak    beaks and feet
THEMES = {}


def _hx(c):
    return tuple(int(c[i:i + 2], 16) for i in (1, 3, 5))


def _mixhex(a, b, t):
    a, b = _hx(a), _hx(b)
    return "#%02x%02x%02x" % tuple(round(a[i] + (b[i] - a[i]) * t) for i in range(3))


def _light(c) -> bool:
    r, g, b = _hx(c)
    return 0.2126 * r + 0.7152 * g + 0.0722 * b > 128


def _theme(bg, text, accent, accent2, panel, warn, muted=None):
    """Turn a compact UI palette into cornholio's full set of colour variables."""
    light = _light(bg)
    return dict(bg=bg, fg=text, dim=muted or _mixhex(text, bg, 0.38),
                faint=_mixhex(text, bg, 0.64), ghost=_mixhex(text, bg, 0.84),
                accent=accent, accent2=accent2, star=_mixhex(text, bg, 0.12),
                snow=_mixhex(text, bg, 0.55) if light else _mixhex(text, "#ffffff", 0.3),
                sel=panel, lift=_mixhex(panel, accent, 0.22), warn=warn,
                body=_mixhex(text, bg, 0.15) if light else _mixhex(bg, text, 0.2),
                beak=_mixhex(warn, accent, 0.5))


def _ui(background, panel, title, border, success, error, warning, cursor, text, changed=None,
        muted=None):
    """A palette in focus's terms. The background is taken a step darker (not
    for a light theme): cornholio is a night-time window."""
    bg = background if _light(background) else _mixhex(background, "#000000", 0.3)
    return _theme(bg, text, cursor, title, panel, warning, muted)


