def _xdg(var: str, fallback: str) -> Path:
    v = os.environ.get(var)
    return Path(v) if v else Path.home() / fallback


CONFIG_DIR = _xdg("XDG_CONFIG_HOME", ".config") / APP
CACHE_DIR = _xdg("XDG_CACHE_HOME", ".cache") / APP
DATA_DIR = _xdg("XDG_DATA_HOME", ".local/share") / APP
LOG_FILE = CACHE_DIR / "cornholio.log"


OLD_NAME = "lull"                 # what cornholio was called before


def migrate_old_name() -> list:
    """First start after the rename: move the old config, data and cache
    folders (logins, folders, order, hidden items, mirrors, the player's
    pairing) to their new names. Nothing is moved if the new one exists."""
    moved = []
    for var, fallback in (("XDG_CONFIG_HOME", ".config"), ("XDG_DATA_HOME", ".local/share"),
                          ("XDG_CACHE_HOME", ".cache")):
        old = _xdg(var, fallback) / OLD_NAME
        new = _xdg(var, fallback) / APP
        if old.is_dir() and not new.exists():
            try:
                shutil.move(str(old), str(new))
                moved.append(f"{old} → {new}")
            except OSError as e:
                print(f"couldn't move {old} to {new}: {e}", file=sys.stderr)
        elif old.is_dir():
            # both exist: bring over what is missing (the newer cornholio data wins)
            for name in ("token.json", "config.json", "soloist.key", "state.json"):
                for o, n in ((old / name, new / name),):
                    if o.is_file() and not n.exists():
                        try:
                            shutil.copy2(str(o), str(n))
                            moved.append(f"{o} → {n}")
                        except OSError:
                            pass
    return moved


def set_demo_dirs(base: Path) -> None:
    """Demo mode keeps its files away from the real ones."""
    global CONFIG_DIR, CACHE_DIR, DATA_DIR, LOG_FILE
    CONFIG_DIR, CACHE_DIR, DATA_DIR = base / "config", base / "cache", base / "data"
    LOG_FILE = CACHE_DIR / "cornholio.log"


def read_json(path: Path, default=None):
    try:
        return json.loads(Path(path).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return default


def write_json(path: Path, data, private: bool = False) -> None:
    """Atomic write: temp file + rename, so a crash never leaves half a file."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".tmp")
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600 if private else 0o644)
    with os.fdopen(fd, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, separators=(",", ":"))
    os.replace(tmp, path)
    if private:
        os.chmod(path, 0o600)


def log(*parts) -> None:
    try:
        LOG_FILE.parent.mkdir(parents=True, exist_ok=True)
        with open(LOG_FILE, "a", encoding="utf-8") as f:
            f.write(time.strftime("%H:%M:%S ") + " ".join(str(p) for p in parts) + "\n")
    except OSError:
        pass


# ── text width (CJK and emoji take two cells, combining marks none) ────────

_ZERO_WIDTH = {"​", "‌", "‍", "⁠", "︎", "️"}


def char_width(ch: str) -> int:
    if ch in _ZERO_WIDTH or unicodedata.combining(ch):
        return 0
    o = ord(ch)
    if o < 32 or 0x7F <= o < 0xA0:
        return 0
    if unicodedata.east_asian_width(ch) in ("W", "F"):
        return 2
    if 0x1F300 <= o <= 0x1FAFF:
        return 2
    return 1


def text_width(s: str) -> int:
    return sum(char_width(c) for c in s)


def clean_text(s) -> str:
    """Names from the API can contain newlines, tabs or control characters."""
    if not s:
        return ""
    s = "".join(" " if (c in "\t\r\n" or unicodedata.category(c) == "Cc") else c for c in str(s))
    return re.sub(r" {2,}", " ", s).strip()


def truncate(s: str, w: int, ell: str = "…") -> str:
    if w <= 0:
        return ""
    if text_width(s) <= w:
        return s
    out, used = [], 0
    for c in s:
        cw = char_width(c)
        if used + cw > w - 1:
            break
        out.append(c)
        used += cw
    return "".join(out).rstrip() + ell


def pad(s: str, w: int, align: str = "left") -> str:
    s = truncate(s, w)
    gap = w - text_width(s)
    if align == "right":
        return " " * gap + s
    if align == "center":
        return " " * (gap // 2) + s + " " * (gap - gap // 2)
    return s + " " * gap


def fold(s: str) -> str:
    """Case- and accent-insensitive form for filtering (Příliš → prilis)."""
    s = unicodedata.normalize("NFKD", s or "")
    return "".join(c for c in s if not unicodedata.combining(c)).casefold()


def fmt_time(ms) -> str:
    s = max(0, int((ms or 0) // 1000))
    if s >= 3600:
        return f"{s // 3600}:{s % 3600 // 60:02d}:{s % 60:02d}"
    return f"{s // 60}:{s % 60:02d}"


def fmt_long(ms) -> str:
    m = int((ms or 0) // 60000)
    if m >= 60:
        return f"{m // 60} h {m % 60} min"
    return f"{m} min"


# ── colour ─────────────────────────────────────────────────────────────────

def hexrgb(h: str):
    h = h.lstrip("#")
    return (int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16))


def mix(a, b, t: float):
    if t <= 0:
        return a
    if t >= 1:
        return b
    return (round(a[0] + (b[0] - a[0]) * t), round(a[1] + (b[1] - a[1]) * t),
            round(a[2] + (b[2] - a[2]) * t))


def ease(t: float) -> float:
    t = 0.0 if t < 0 else 1.0 if t > 1 else t
    return t * t * (3 - 2 * t)


def ease_io(t: float) -> float:
    """Long, soft ease-in-out (cubic)."""
    t = 0.0 if t < 0 else 1.0 if t > 1 else t
    return 4 * t * t * t if t < 0.5 else 1 - (-2 * t + 2) ** 3 / 2


class Palette:
    """The live colour variables. Read as C.fg, C.dim, ... at draw time.
    switch() cross-fades every variable to another theme."""

    KEYS = list(THEMES[THEME_ORDER[0]].keys())
    FADE = 0.9

    def __init__(self, name: str):
        self.name = name if name in THEMES else THEME_ORDER[0]
        self.prev = self.name
        self._dst = {k: hexrgb(v) for k, v in THEMES[self.name].items()}
        self._src = dict(self._dst)
        self._t0 = -10.0
        for k, v in self._dst.items():
            setattr(self, k, v)

    def switch(self, name: str, now: float) -> None:
        self._src = {k: getattr(self, k) for k in self.KEYS}
        self.prev = self.name
        self.name = name
        self._dst = {k: hexrgb(v) for k, v in THEMES[name].items()}
        self._t0 = now

    @property
    def fading(self) -> bool:
        return time.monotonic() - self._t0 < self.FADE

    def update(self, now: float) -> None:
        t = (now - self._t0) / self.FADE
        if t >= 1.05:
            return
        e = ease(t)
        for k in self.KEYS:
            setattr(self, k, mix(self._src[k], self._dst[k], e))

    def fade_k(self) -> float:
        """How far the current theme cross-fade has come, 0..1."""
        return ease((time.monotonic() - self._t0) / self.FADE)

    def blend(self, table: dict, default: str = "default"):
        """A per-theme tuple of hex colours, cross-faded like the palette."""
        cur = [hexrgb(c) for c in table.get(self.name, table[default])]
        k = ease((time.monotonic() - self._t0) / self.FADE)
        if k >= 1:
            return cur
        old = [hexrgb(c) for c in table.get(self.prev, table[default])]
        return [mix(a, b, k) for a, b in zip(old, cur)]

    def toward_bg(self, color, t: float):
        """Fade a colour toward the background: t=0 colour, t=1 background."""
        return mix(color, self.bg, t)


C = Palette(THEME_ORDER[0])

