#  terminal: raw mode, alternate screen, keyboard and mouse input
# ════════════════════════════════════════════════════════════════════════════

class TerminalGone(Exception):
    """The terminal went away (window closed); cornholio leaves quietly."""


class Terminal:
    ENTER = ("\x1b[?1049h"      # alternate screen
             "\x1b[?25l"        # hide cursor
             "\x1b[?7l"         # no autowrap (last cell is safe to write)
             "\x1b[?1003h"      # mouse motion too (it only paints; it never controls)
             "\x1b[?1006h"      # SGR mouse encoding
             "\x1b[?2004h"      # bracketed paste: a pasted link arrives whole, never as keys
             "\x1b[2J")
    LEAVE = ("\x1b[?2004l\x1b[?1006l\x1b[?1003l\x1b[?1000l\x1b[?7h\x1b[0m\x1b[?25h\x1b[?1049l")

    def __init__(self):
        self.ifd = sys.stdin.fileno()
        self.ofd = sys.stdout.fileno()
        self._old = None
        self.dyn_bg = False      # its background colour was set (translucency): reset it on the way out

    def __enter__(self):
        self._old = termios.tcgetattr(self.ifd)
        tty.setraw(self.ifd)
        self.write(self.ENTER)
        return self

    def __exit__(self, *exc):
        self.restore()

    def restore(self):
        if self._old is not None:
            try:
                if self.dyn_bg:
                    self.write("\x1b]111\x1b\\")       # OSC 111: the background it was configured with
                    self.dyn_bg = False
                self.write(self.LEAVE)
                termios.tcsetattr(self.ifd, termios.TCSADRAIN, self._old)
            except (termios.error, OSError, TerminalGone):
                pass                # the window was closed: nothing to give back, and the saves still run
            self._old = None

    def write(self, s: str) -> None:
        data = s.encode("utf-8", "replace")
        while data:
            try:
                n = os.write(self.ofd, data)
            except BlockingIOError:
                select.select([], [self.ofd], [], 0.05)
                continue
            except InterruptedError:
                continue
            except OSError as e:
                if e.errno in (5, 9, 32):      # EIO, EBADF, EPIPE: the window was closed
                    raise TerminalGone() from None
                raise
            data = data[n:]

    def size(self):
        try:
            s = os.get_terminal_size(self.ofd)
            return max(1, s.columns), max(1, s.lines)
        except OSError:
            return 80, 24


class Mouse(tuple):
    """(button, x, y, pressed) from SGR mouse reports; 0-based coordinates."""
    __slots__ = ()

    @property
    def button(self): return self[0]

    @property
    def x(self): return self[1]

    @property
    def y(self): return self[2]

    @property
    def pressed(self): return self[3]


_CSI_FINAL = {"A": "up", "B": "down", "C": "right", "D": "left", "H": "home", "F": "end",
              "Z": "btab", "P": "f1", "Q": "f2", "R": "f3", "S": "f4"}
_CSI_TILDE = {"1": "home", "7": "home", "4": "end", "8": "end", "5": "pgup", "6": "pgdn",
              "3": "del", "2": "ins"}
_SS3 = {"A": "up", "B": "down", "C": "right", "D": "left", "H": "home", "F": "end",
        "P": "f1", "Q": "f2", "R": "f3", "S": "f4"}


class Paste(tuple):
    """Text pasted into the terminal (bracketed paste), as one event."""
    __slots__ = ()

    @property
    def text(self): return self[0]


def parse_keys(buf: str):
    """Split raw input into key names. Returns (keys, unparsed_rest)."""
    keys, i, n = [], 0, len(buf)
    while i < n:
        c = buf[i]
        if c == "\x1b":
            if i + 1 >= n:
                break  # maybe the start of a sequence; caller decides on timeout
            nx = buf[i + 1]
            if nx == "[":
                j = i + 2
                while j < n and not ("@" <= buf[j] <= "~"):
                    j += 1
                if j >= n:
                    break
                params, final = buf[i + 2:j], buf[j]
                if params == "200" and final == "~":          # a paste: up to its end marker
                    end = buf.find("\x1b[201~", j + 1)
                    if end < 0:
                        break
                    keys.append(Paste((buf[j + 1:end],)))
                    i = end + 6
                    continue
                i = j + 1
                if params.startswith("<") and final in "Mm":
                    try:
                        b, x, y = (int(v) for v in params[1:].split(";"))
                        keys.append(Mouse((b, x - 1, y - 1, final == "M")))
                    except ValueError:
                        pass
                elif final == "~":
                    k = _CSI_TILDE.get(params.split(";")[0])
                    if k:
                        keys.append(k)
                elif final in _CSI_FINAL:
                    keys.append(_CSI_FINAL[final])
                continue
            if nx == "O":
                if i + 2 >= n:
                    break
                k = _SS3.get(buf[i + 2])
                if k:
                    keys.append(k)
                i += 3
                continue
            if nx == "\x1b":
                keys.append("esc")
                i += 1
                continue
            keys.append("alt-" + nx)
            i += 2
            continue
        if c in "\r\n":
            keys.append("enter")
        elif c in "\x7f\x08":
            keys.append("backspace")
        elif c == "\t":
            keys.append("tab")
        elif c == "\x00":
            pass
        elif ord(c) < 32:
            keys.append("ctrl-" + chr(ord(c) + 96))
        else:
            keys.append(c)
        i += 1
    return keys, buf[i:]


class Input:
    ESC_WAIT = 0.03

    def __init__(self, fd: int):
        self.fd = fd
        self.dec = codecs.getincrementaldecoder("utf-8")("replace")
        self.buf = ""

    def _read_available(self) -> bool:
        try:
            data = os.read(self.fd, 4096)
        except (BlockingIOError, InterruptedError):
            return False
        if not data:
            return False
        self.buf += self.dec.decode(data)
        return True

    def read(self, timeout: float):
        try:
            r, _, _ = select.select([self.fd], [], [], max(0.0, timeout))
        except InterruptedError:
            return []
        if r:
            self._read_available()
        keys, self.buf = parse_keys(self.buf)
        if self.buf.startswith("\x1b"):
            # A lone Esc, or the start of a sequence that is still arriving.
            r, _, _ = select.select([self.fd], [], [], self.ESC_WAIT)
            if r and self._read_available():
                more, self.buf = parse_keys(self.buf)
                keys += more
            if self.buf == "\x1b":
                keys.append("esc")
                self.buf = ""
            elif self.buf.startswith("\x1b[200~"):
                if len(self.buf) > 65536:
                    self.buf = ""      # a paste that never ends
            elif self.buf.startswith("\x1b") and len(self.buf) > 32:
                self.buf = ""  # garbage; never let it block input
        return keys

# ════════════════════════════════════════════════════════════════════════════
#  canvas: a grid of (char, fg, bg, bold) cells, and a span-diff renderer
# ════════════════════════════════════════════════════════════════════════════

class Canvas:
    def __init__(self, w: int, h: int, bg):
        self.w, self.h = w, h
        self.reset(bg)

    def reset(self, bg) -> None:
        n = self.w * self.h
        self.ch = [" "] * n
        self.fg = [bg] * n
        self.bg = [bg] * n
        self.bold = [False] * n
        self.base = bg

    def resize(self, w: int, h: int, bg) -> None:
        self.w, self.h = w, h
        self.reset(bg)

    def _clear_wide_at(self, i: int, x: int) -> None:
        # Overwriting half of a wide character must blank the other half.
        if self.ch[i] == "" and x > 0:
            self.ch[i - 1] = " "
        elif x + 1 < self.w and self.ch[i + 1] == "" and self.ch[i] != "":
            self.ch[i + 1] = " "

    def put(self, x: int, y: int, ch: str, fg, bg=None, bold: bool = False) -> None:
        if not (0 <= x < self.w and 0 <= y < self.h):
            return
        i = y * self.w + x
        cw = char_width(ch)
        if cw == 2 and x + 1 >= self.w:
            ch, cw = "…", 1
        self._clear_wide_at(i, x)
        self.ch[i] = ch
        self.fg[i] = fg
        self.bold[i] = bold
        if bg is not None:
            self.bg[i] = bg
        if cw == 2:
            self._clear_wide_at(i + 1, x + 1)
            self.ch[i + 1] = ""
            self.fg[i + 1] = fg
            if bg is not None:
                self.bg[i + 1] = bg

    def text(self, x: int, y: int, s: str, fg, bg=None, bold: bool = False, maxw=None) -> int:
        """Draw a string; returns the x after it. Clips to maxw cells."""
        if y < 0 or y >= self.h:
            return x + text_width(s)
        limit = self.w if maxw is None else min(self.w, x + maxw)
        for c in s:
            cw = char_width(c)
            if cw == 0:
                continue
            if x + cw > limit:
                break
            if x >= 0:
                self.put(x, y, c, fg, bg, bold)
            x += cw
        return x

    def fill(self, x: int, y: int, w: int, h: int, bg, ch: str = " ") -> None:
        x0, x1 = max(0, x), min(self.w, x + w)
        if x1 <= x0:
            return
        for yy in range(max(0, y), min(self.h, y + h)):
            a = yy * self.w
            if x0 > 0 and self.ch[a + x0] == "":
                self.ch[a + x0 - 1] = " "
            if x1 < self.w and self.ch[a + x1] == "":
                self.ch[a + x1] = " "
            for i in range(a + x0, a + x1):
                self.ch[i] = ch
                self.bg[i] = bg
                self.fg[i] = bg
                self.bold[i] = False

    def tint(self, x: int, y: int, w: int, bg) -> None:
        """Change the background of a row span without touching the text."""
        if not 0 <= y < self.h:
            return
        a = y * self.w
        for i in range(a + max(0, x), a + min(self.w, x + w)):
            self.bg[i] = bg

    def get_bg(self, x: int, y: int):
        if 0 <= x < self.w and 0 <= y < self.h:
            return self.bg[y * self.w + x]
        return self.base

    def is_blank(self, x: int, y: int) -> bool:
        return 0 <= x < self.w and 0 <= y < self.h and self.ch[y * self.w + x] == " "


class Renderer:
    """Writes only the cells that changed since the last frame, wrapped in
    synchronized-output markers so the terminal never shows half a frame.

    Translucent (Settings → translucency), every cell on the theme's background
    is left to the terminal's own background (SGR 49), which is the one a
    terminal draws at its opacity (Alacritty's window.opacity, kitty's
    background_opacity, foot's alpha…: they all leave coloured cells solid). The
    terminal is told that its background is the theme's (OSC 11), so the colour
    stays cornholio's and only the opacity is the terminal's; OSC 111 gives it
    back its own colour when translucency goes off or cornholio quits."""

    def __init__(self, term: Terminal):
        self.term = term
        self.prev = None
        self._sgr = {}
        self.translucent = False
        self._clear = None          # translucent: the background the terminal was told it has

    def invalidate(self) -> None:
        self.prev = None

    def _sgr_for(self, fg, bg, bold) -> str:
        key = (fg, bg, bold)
        s = self._sgr.get(key)
        if s is None:
            if len(self._sgr) > 20000:
                self._sgr.clear()
            if bg == self._clear:                     # the terminal's own background
                s = f"\x1b[{'1' if bold else '22'};38;2;{fg[0]};{fg[1]};{fg[2]};49m"
            else:
                s = (f"\x1b[{'1' if bold else '22'};38;2;{fg[0]};{fg[1]};{fg[2]};"
                     f"48;2;{bg[0]};{bg[1]};{bg[2]}m")
            self._sgr[key] = s
        return s

    def _background(self, cv: Canvas, out) -> None:
        """Translucency on, off, or a new theme background (it cross-fades too)."""
        clear = tuple(cv.base) if self.translucent else None
        if clear == self._clear:
            return
        if (clear is None) != (self._clear is None):
            self.prev = None                          # on or off: every cell anew
        self._sgr.clear()
        if clear is not None:
            out.append("\x1b]11;#%02x%02x%02x\x1b\\" % clear)
            self.term.dyn_bg = True
        else:
            out.append("\x1b]111\x1b\\")
            self.term.dyn_bg = False
        self._clear = clear

    def flush(self, cv: Canvas) -> None:
        out = ["\x1b[?2026h"]
        if self.translucent or self._clear is not None:
            self._background(cv, out)
        p = self.prev
        full = p is None or p[0] != cv.w or p[1] != cv.h
        if full:
            out.append("\x1b[0m\x1b[2J")
        w = cv.w
        ch, fg, bg, bd = cv.ch, cv.fg, cv.bg, cv.bold
        if not full:
            pch, pfg, pbg, pbd = p[2], p[3], p[4], p[5]
        last_sgr = None
        for y in range(cv.h):
            a, b = y * w, y * w + w
            if not full and ch[a:b] == pch[a:b] and fg[a:b] == pfg[a:b] \
                    and bg[a:b] == pbg[a:b] and bd[a:b] == pbd[a:b]:
                continue
            x = 0
            while x < w:
                i = a + x
                if not full and ch[i] == pch[i] and fg[i] == pfg[i] and bg[i] == pbg[i] \
                        and bd[i] == pbd[i]:
                    x += 1
                    continue
                if ch[i] == "" and x > 0:
                    x -= 1
                # extend the run while changes keep coming (gaps of < 4 are bridged)
                start, last, j = x, x, x
                while j < w:
                    k = a + j
                    if full or ch[k] != pch[k] or fg[k] != pfg[k] or bg[k] != pbg[k] \
                            or bd[k] != pbd[k]:
                        last = j
                    elif j - last > 4:
                        break
                    j += 1
                if last + 1 < w and ch[a + last + 1] == "":
                    last += 1
                out.append(f"\x1b[{y + 1};{start + 1}H")
                for jj in range(start, last + 1):
                    k = a + jj
                    c = ch[k]
                    if c == "":
                        continue
                    s = self._sgr_for(fg[k], bg[k], bd[k])
                    if s != last_sgr:
                        out.append(s)
                        last_sgr = s
                    out.append(c)
                x = last + 1
        out.append("\x1b[?2026l")
        if len(out) > 2 or full:
            self.term.write("".join(out))
        self.prev = (cv.w, cv.h, ch[:], fg[:], bg[:], bd[:])


# ── pixel sprites: two vertical pixels per cell using half blocks ──────────

def draw_pixels(cv: Canvas, x: int, y: int, rows, colors: dict, mirror: bool = False,
                clip=None) -> None:
    """rows: list of equal-length strings; each char is a palette key or '.'.
    The sprite's pixel row 0 starts at the top half of cell row y.
    Transparent pixels keep whatever is underneath (background colour)."""
    if not rows:
        return
    h = len(rows)
    for cy in range(0, h, 2):
        top = rows[cy]
        bot = rows[cy + 1] if cy + 1 < h else "." * len(top)
        if mirror:
            top, bot = top[::-1], bot[::-1]
        yy = y + cy // 2
        if not 0 <= yy < cv.h:
            continue
        for cx in range(len(top)):
            xx = x + cx
            if not 0 <= xx < cv.w:
                continue
            if clip and not clip(xx, yy):
                continue
            t, b = top[cx], bot[cx]
            if t == "." and b == ".":
                continue
            under = cv.get_bg(xx, yy)
            tc = colors.get(t) if t != "." else None
            bc = colors.get(b) if b != "." else None
            if tc and bc:
                if tc == bc:
                    cv.put(xx, yy, "█", tc, under)
                else:
                    cv.put(xx, yy, "▀", tc, bc)
            elif tc:
                cv.put(xx, yy, "▀", tc, under)
            elif bc:
                cv.put(xx, yy, "▄", bc, under)

# ════════════════════════════════════════════════════════════════════════════
#  fonts: hand-drawn pixel letters for the hero title
# ════════════════════════════════════════════════════════════════════════════
# Glyphs are written as rows separated by "/", '#' = lit pixel. Letters are
# capitals only (titles are set in caps, like a departure board); accents are
# drawn separately and stacked on top, so ČŘŽÁÉÍÚŮ etc. keep their marks.

def _g(s: str):
    return s.split("/")


