# ════════════════════════════════════════════════════════════════════════════
#  stroke faces: Hershey strokes drawn with a round pen, then turned into
#  braille dots, quadrant blocks, or hand-tuned ASCII
# ════════════════════════════════════════════════════════════════════════════

def _parse_hershey():
    table = {}
    for i, g in enumerate(HERSHEY_FUTURAL):
        left, right = ord(g[0]) - 82, ord(g[1]) - 82
        strokes, cur = [], []
        for k in range(2, len(g) - 1, 2):
            a, b = g[k], g[k + 1]
            if a == " " and b == "R":
                if cur:
                    strokes.append(cur)
                cur = []
                continue
            cur.append((ord(a) - 82, ord(b) - 82))
        if cur:
            strokes.append(cur)
        table[chr(32 + i)] = (left, right, strokes)
    return table


HERSHEY = _parse_hershey()
H_CAP_TOP, H_BASE, H_XTOP, H_DESC = -12, 9, -5, 16

_LOWER_ALIAS = {"ø": "o", "ł": "l", "đ": "d", "æ": "ae", "œ": "oe", "ß": "ss", "ı": "i",
                "ð": "d", "þ": "th"}


def _circle(r, n=10):
    return [(r * math.cos(2 * math.pi * k / n), r * math.sin(2 * math.pi * k / n))
            for k in range(n + 1)]


# accent strokes, drawn in a small zone above the letter (units, y down)
ACCENT_STROKES = {
    "\u0301": [[(-1.2, 1.5), (1.8, -1.5)]],                       # acute
    "\u0300": [[(1.2, 1.5), (-1.8, -1.5)]],                       # grave
    "\u030c": [[(-2.5, -1.5), (0, 1.5), (2.5, -1.5)]],            # caron
    "\u0302": [[(-2.5, 1.5), (0, -1.5), (2.5, 1.5)]],             # circumflex
    "\u0308": [[(-2.5, 0), (-2.5, 0)], [(2.5, 0), (2.5, 0)]],     # diaeresis
    "\u030a": [_circle(1.7)],                                     # ring
    "\u0303": [[(-3, 1), (-1.5, -0.8), (1.5, 0.8), (3, -1)]],      # tilde
    "\u030b": [[(-2.6, 1.5), (-0.6, -1.5)], [(0.6, 1.5), (2.6, -1.5)]],
    "\u0307": [[(0, 0), (0, 0)]],                                 # dot above
    "\u0306": [[(-2.5, -1.5), (-1.2, 0.8), (1.2, 0.8), (2.5, -1.5)]],  # breve
}
_BELOW = {
    "\u0327": [[(0, 9.5), (1.5, 11), (0, 12.5), (-1.5, 12.5)]],     # cedilla
    "\u0328": [[(1.5, 9), (-0.5, 11), (0.5, 12.5), (2, 12.5)]],     # ogonek
}


def clusters_case(text: str):
    """Like clusters(), but keeps the title's case (stroke faces have lowercase)."""
    t = "".join(_ALIAS.get(c, _LOWER_ALIAS.get(c, c)) for c in text)
    t = unicodedata.normalize("NFD", t)
    base, marks = None, []
    for c in t:
        if unicodedata.combining(c):
            if base is not None:
                marks.append(c)
            continue
        if base is not None:
            yield base, marks
        base, marks = c, []
    if base is not None:
        yield base, marks


def stroke_glyph(base: str, marks):
    """(advance_left, advance_right, [polylines], [accent polylines])."""
    g = HERSHEY.get(base)
    if g is None:
        if base.isspace():
            g = HERSHEY[" "]
        else:                               # unknown: a quiet middle dot
            return -4, 4, [[(0, -2), (0, -2)]], []
    left, right, strokes = g
    strokes = [list(s) for s in strokes]
    accents = []
    if not marks:
        return left, right, strokes, accents
    xs = [p[0] for s in strokes for p in s] or [0]
    cx = (min(xs) + max(xs)) / 2
    upper = base.isupper() or base.isdigit()
    if base in "ij" and any(m in ACCENT_STROKES for m in marks):
        strokes = [s for s in strokes if max(p[1] for p in s) > H_XTOP - 1]   # drop the dot
    for m in marks:
        if m == "\u030c" and base in "dtlL":
            # Czech ď ť ľ Ľ: the háček becomes a small apostrophe to the right
            rx = max(xs) + 2.5
            top = H_CAP_TOP if base != "t" else -10
            accents.append([(rx + 0.6, top), (rx - 0.6, top + 3.2)])
            right += 2
            continue
        if m in _BELOW:
            accents += [[(cx + x, y) for x, y in s] for s in _BELOW[m]]
            continue
        acc = ACCENT_STROKES.get(m)
        if not acc:
            continue
        zy = -15.5 if upper or base in "bdfhklt" else -8.6
        accents += [[(cx + x, zy + y) for x, y in s] for s in acc]
    return left, right, strokes, accents


def stroke_line(text: str, tracking: float = 0.0, cond: float = 1.0):
    """All polylines for a line of text, laid out left to right in units.
    cond < 1 condenses the letters horizontally (poster lettering is narrow)."""
    polys, accents = [], []
    x = 0.0
    top = H_CAP_TOP
    for base, marks in clusters_case(text):
        left, right, strokes, accs = stroke_glyph(base, marks)
        for group, out in ((strokes, polys), (accs, accents)):
            for s in group:
                pts = [(x + (px - left) * cond, py) for px, py in s]
                out.append(pts)
                for _, py in pts:
                    top = min(top, py)
        x += (right - left) * cond + tracking
    return (polys, accents), max(0.0, x - tracking), top


def stroke_width_units(text: str, tracking: float = 0.0, cond: float = 1.0) -> float:
    w = 0.0
    n = 0
    for base, marks in clusters_case(text):
        g = HERSHEY.get(base)
        if g is None:
            w += 8
        else:
            w += g[1] - g[0] + (2 if marks and "\u030c" in marks and base in "dtlL" else 0)
        n += 1
    return w * cond + tracking * max(0, n - 1)


# ── raster and cell conversion ─────────────────────────────────────────────

_DISKS = {}


def _disk(rx: float, ry: float):
    key = (round(rx, 2), round(ry, 2))
    d = _DISKS.get(key)
    if d is None:
        d = []
        ix, iy = int(math.ceil(rx)), int(math.ceil(ry))
        for dy in range(-iy, iy + 1):
            for dx in range(-ix, ix + 1):
                if rx < 0.5 and ry < 0.5:
                    if dx == 0 and dy == 0:
                        d.append((0, 0))
                elif (dx / max(rx, 0.5)) ** 2 + (dy / max(ry, 0.5)) ** 2 <= 1.0:
                    d.append((dx, dy))
        _DISKS[key] = d
    return d


def raster_polys(polys, W, H, sx, sy, ox, oy, rx, ry):
    grid = bytearray(W * H)
    disk = _disk(rx, ry)
    step = 0.45
    for pts in polys:
        if len(pts) == 1:
            pts = [pts[0], pts[0]]
        for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
            ax, ay = ox + x0 * sx, oy + y0 * sy
            bx, by = ox + x1 * sx, oy + y1 * sy
            n = max(1, int(math.hypot(bx - ax, by - ay) / step))
            for k in range(n + 1):
                t = k / n
                cx = int(ax + (bx - ax) * t + 0.5)
                cy = int(ay + (by - ay) * t + 0.5)
                for dx, dy in disk:
                    px, py = cx + dx, cy + dy
                    if 0 <= px < W and 0 <= py < H:
                        grid[py * W + px] = 1
    return grid


_QUAD = " ▘▝▀▖▌▞▛▗▚▐▜▄▙▟█"

# ASCII templates on a 2x4 grid (rows top→bottom, "#"=ink). The vocabulary is
# the one the classic FIGlet poster fonts use: 8 for body, d b P Y for the
# rounded corners, quotes and dots for the thin ends.
_ASCII_TEMPLATES = [
    (" ", "..|..|..|.."),
    ("8", "##|##|##|##"),
    ("8", "#.|#.|#.|#."), ("8", ".#|.#|.#|.#"),
    ("d", ".#|##|##|##"), ("d", "..|.#|##|##"), ("d", "..|.#|.#|##"),
    ("b", "#.|##|##|##"), ("b", "..|#.|##|##"), ("b", "..|#.|#.|##"),
    ("P", "##|##|##|#."), ("P", "##|##|#.|.."), ("P", "##|#.|#.|.."),
    ("Y", "##|##|##|.#"), ("Y", "##|##|.#|.."), ("Y", "##|.#|.#|.."),
    ('"', "##|##|..|.."), ('"', "##|..|..|.."),
    ("o", "..|..|##|##"), ("o", "..|##|##|.."),
    (".", "..|..|..|##"), (".", "..|..|.#|.#"), (".", "..|..|#.|#."),
    ("'", ".#|.#|..|.."), ("`", "#.|#.|..|.."),
    (",", "..|..|.#|#."), ("/", ".#|.#|#.|#."), ("\\", "#.|#.|.#|.#"),
    ("8", "##|##|##|.."), ("8", "..|##|##|##"),
]


def _ascii_lut():
    tpl = []
    for ch, pat in _ASCII_TEMPLATES:
        rows = pat.split("|")
        bits = 0
        for r, row in enumerate(rows):
            for c, v in enumerate(row):
                if v == "#":
                    bits |= 1 << (r * 2 + c)
        tpl.append((ch, bits))
    lut = []
    for m in range(256):
        if m == 0:
            lut.append(" ")
            continue
        best, bd = "8", 99
        for ch, bits in tpl:
            if ch == " ":
                continue
            d = bin(m ^ bits).count("1")
            if d < bd:
                best, bd = ch, d
        n = bin(m).count("1")
        if n == 1:          # a single stray pixel: only the tiniest marks
            best = {0: "`", 1: "'", 6: ",", 7: "."}.get(m.bit_length() - 1, ".")
        lut.append(best)
    return lut


_ASCII_LUT = _ascii_lut()


def grid_to_cells(grid, W, H, kind):
    out = []
    if kind == "braille":
        bitpos = ((0, 0, 0x01), (0, 1, 0x02), (0, 2, 0x04), (1, 0, 0x08), (1, 1, 0x10),
                  (1, 2, 0x20), (0, 3, 0x40), (1, 3, 0x80))
        for cy in range(H // 4):
            for cx in range(W // 2):
                m = 0
                for dx, dy, b in bitpos:
                    if grid[(cy * 4 + dy) * W + cx * 2 + dx]:
                        m |= b
                if m:
                    out.append((cx, cy, chr(0x2800 + m)))
    elif kind == "quad":
        for cy in range(H // 2):
            for cx in range(W // 2):
                i = cy * 2 * W + cx * 2
                m = grid[i] | grid[i + 1] << 1 | grid[i + W] << 2 | grid[i + W + 1] << 3
                if m:
                    out.append((cx, cy, _QUAD[m]))
    else:
        for cy in range(H // 4):
            for cx in range(W // 2):
                m = 0
                for r in range(4):
                    i = (cy * 4 + r) * W + cx * 2
                    m |= grid[i] << (r * 2) | grid[i + 1] << (r * 2 + 1)
                if m:
                    out.append((cx, cy, _ASCII_LUT[m]))
    return out


class StrokeFace:
    """A continuously scalable face. weight is the pen radius as a share of
    the cap height; min_cap is the smallest legible cap height in rows."""

    def __init__(self, name, kind, weight, min_r, min_cap, tracking=0.0, upper=False, cond=1.0):
        self.name, self.kind, self.weight, self.min_r = name, kind, weight, min_r
        self.min_cap, self.tracking, self.upper, self.cond = min_cap, tracking, upper, cond
        self.sub = (2, 2) if kind == "quad" else (2, 4)


STROKE_FACES = {
    # the pen of focus's braille digits: about a twentieth of the capital
    "dots": StrokeFace("dots", "braille", 0.055, 1.0, 2.4, tracking=1.0),
    # obeliks's large sizes; below a capital of about eight rows the drawn strokes
    # turn to mush, and the hand-drawn alphabets take over (see cell fonts)
    "obeliks": StrokeFace("obeliks", "ascii", 0.095, 1.0, 8.0, tracking=3.5, upper=True,
                          cond=0.68),
}


def _box(text: str, face: StrokeFace):
    """Vertical extent in units. Descender room is always reserved for text
    with letters, so the baseline (and the gap to the label) never moves."""
    has_upper_acc = any(m and (b.isupper() or b in "bdfhklt") and
                        any(x in ACCENT_STROKES for x in m)
                        for b, m in clusters_case(text))
    top = -17.5 if has_upper_acc else H_CAP_TOP - 0.5
    no_desc = face.upper or re.fullmatch(r"[\d: .,\-–]+", text)
    bottom = H_BASE + 0.5 if no_desc else H_DESC + 0.5
    return top, bottom


def _splits(words, n):
    """All ways to break a list of words into n non-empty lines."""
    if n == 1:
        yield [" ".join(words)]
        return
    for k in range(1, len(words) - n + 2):
        for rest in _splits(words[k:], n - 1):
            yield [" ".join(words[:k])] + rest


def stroke_fit(text: str, face: StrokeFace, area_rows: int, maxw: int, gap: int = 1):
    """Largest scale (cells per unit) and line split that fits, or None.
    One line is preferred; more lines only when they are clearly bigger."""
    top, bottom = _box(text, face)
    box = bottom - top
    vmax = 2 * 12 / 21                       # never taller than a 12-row capital
    words = text.split(" ")
    best = None
    for n in (1, 2, 3):
        if n > len(words) or area_rows < n * 2:
            break
        widest = None
        if len(words) <= 14:
            for lines in _splits(words, n):
                wmax = max(stroke_width_units(ln, face.tracking, face.cond) for ln in lines)
                if widest is None or wmax < widest[0]:
                    widest = (wmax, lines)
        else:
            widest = (stroke_width_units(text, face.tracking, face.cond), [text]) if n == 1 else None
        if not widest or widest[0] <= 0:
            continue
        v = min((area_rows - (n - 1) * gap) / n * 2 / box, maxw / widest[0], vmax)
        if best is None or v > best[0] * 1.18:
            best = (v, widest[1])
    if best is None or 21 * best[0] / 2 < face.min_cap:
        return None
    return best[0], best[1], top, bottom


def stroke_cells(text_lines, face: StrokeFace, v: float, top: float, bottom: float, gap=1):
    """Cells (x relative to the line centre, y from the block top) and width."""
    sx_sub, sy_sub = face.sub
    px_x = sx_sub * v              # pixels per unit, horizontally
    px_y = sy_sub * v / 2          # and vertically (a cell is twice as tall as wide)
    line_rows = int(math.ceil((bottom - top) * v / 2))
    cap_rows = 21 * v / 2
    # the pen is round in what you see: equal radius in visual units both ways
    r_vis = face.weight * cap_rows * 2                 # visual units (1 col = 1, 1 row = 2)
    rx = max(face.min_r, r_vis * sx_sub)
    ry = rx * (sy_sub / 2) / sx_sub
    pad_cols = int(math.ceil(rx / sx_sub)) + 1
    cells = []
    width = 0
    for li, line in enumerate(text_lines):
        (polys, accents), wu, _ = stroke_line(line, face.tracking, face.cond)
        Wc = int(math.ceil(wu * v)) + 2 * pad_cols
        W, H = Wc * sx_sub, line_rows * sy_sub
        grid = raster_polys(polys, W, H, px_x, px_y, pad_cols * sx_sub, -top * px_y, rx, ry)
        if accents:                       # accents get a finer pen, or they turn into blobs
            g2 = raster_polys(accents, W, H, px_x, px_y, pad_cols * sx_sub, -top * px_y,
                              max(0.0 if face.kind == "braille" else 0.5, rx * 0.55),
                              max(0.0 if face.kind == "braille" else 0.5, ry * 0.55))
            grid = bytearray(a | b for a, b in zip(grid, g2))
        lc = grid_to_cells(grid, W, H, face.kind)
        width = max(width, Wc - 2 * pad_cols)
        y0 = li * (line_rows + gap)
        for cx, cy, ch in lc:
            cells.append((cx - Wc // 2, y0 + cy, ch))
    total_rows = len(text_lines) * line_rows + (len(text_lines) - 1) * gap
    return cells, width, total_rows

# ════════════════════════════════════════════════════════════════════════════
#  cell fonts: hand-drawn ASCII capitals and square blocks
# ════════════════════════════════════════════════════════════════════════════
# These faces draw titles in plain capitals: diacritics are folded away
# (Č → C, é → e) so the letters stay clean. The full name, accents and all,
# is always in the label under the title.
#
#   obeliks  capitals in the style of focus's ASCII digits at five and four
#            rows, the small sizes of the obeliks face (its large sizes are
#            strokes in the same 8 d b P Y vocabulary, see strokes)
#   blocks   square 3x5 letters, tty-clock style: no rounded corners

_FOLD = {"ø": "o", "Ø": "O", "ł": "l", "Ł": "L", "đ": "d", "Đ": "D", "ß": "SS", "ẞ": "SS",
         "æ": "AE", "Æ": "AE", "œ": "OE", "Œ": "OE", "þ": "TH", "Þ": "TH", "ı": "i",
         "‘": "'", "’": "'", "‚": ",", "“": "'", "”": "'", "„": ",", "\"": "'", "`": "'",
         "´": "'", "–": "-", "—": "-", "−": "-", "…": "...", "×": "X", "¿": "?", "¡": "!",
         "{": "(", "}": ")", "[": "(", "]": ")", "|": "!", "\\": "/", "_": "-", ";": ":",
         "·": "-"}


def fold_marks(text: str) -> str:
    """'Řeka Ůsvitů' → 'Reka Usvitu': the same letters without their marks."""
    t = "".join(_FOLD.get(c, c) for c in text)
    t = unicodedata.normalize("NFD", t)
    t = "".join(c for c in t if not unicodedata.combining(c))
    return re.sub(r"\s+", " ", t).strip()


def fold_title(text: str) -> str:
    """'Řeka Ůsvitů' → 'REKA USVITU': plain capitals, no marks."""
    return fold_marks(text).upper()


