def _focus_compact(rows_by_char):
    """Trim each digit to its ink and centre it in the widest digit's width, the
    way the FIGlet sizes are padded."""
    trimmed = {}
    for c, rows in rows_by_char.items():
        w = max(len(r) for r in rows)
        rows = [r.ljust(w) for r in rows]
        cols = [x for x in range(w) if any(r[x] != " " for r in rows)]
        trimmed[c] = [r[cols[0]:cols[-1] + 1] for r in rows] if cols else rows
    w = max(len(trimmed[d][0]) for d in "0123456789")
    out = {}
    for c, rows in trimmed.items():
        if c == ":":
            out[c] = tuple(rows)
            continue
        lw = len(rows[0])
        left = (w - lw + (1 if c == "1" else 0)) // 2
        out[c] = tuple(" " * left + r + " " * (w - lw - left) for r in rows)
    return out


