class HelpPlate:
    def hints(self, app):
        return [("esc", "close")]

    def _lines(self, sections):
        out = []
        for title, items in sections:
            out.append(("h" if items else "n", title))
            out += [("k", a, b) for a, b in items]
            out.append(("", ""))
        return out[:-1]

    def draw(self, cv, app, now) -> None:
        colw = 46
        n = 3 if cv.w >= 3 * colw + 6 and cv.h < 40 else 2 if cv.w >= 2 * colw + 6 else 1
        # whole sections, in order, spread so the columns come out about even
        sizes = [len(items) + 2 for _, items in HELP]
        target = sum(sizes) / n
        groups, acc = [[]], 0
        for sec, size in zip(HELP, sizes):
            if groups[-1] and acc + size / 2 > target and len(groups) < n:
                groups.append([])
                acc = 0
            groups[-1].append(sec)
            acc += size
        cols = [self._lines(g) for g in groups]
        w = colw * len(cols) + 4
        h = min(cv.h - 2, max(len(c) for c in cols) + 4)
        x, y, w, h = plate(cv, w, h)
        for ci, col in enumerate(cols):
            cx = x + 3 + ci * colw
            for i, ln in enumerate(col[:h - 4]):
                yy = y + 2 + i
                if ln[0] == "h":
                    cv.text(cx, yy, ln[1], C.dim, C.sel)
                elif ln[0] == "n":
                    cv.text(cx, yy, truncate(ln[1], colw - 2), C.faint, C.sel)
                elif ln[0] == "k":
                    cv.text(cx + 2, yy, ln[1], mix(C.dim, C.accent, 0.4), C.sel)
                    cv.text(cx + 18, yy, truncate(ln[2], colw - 20), C.faint, C.sel)
        foot = "cornholio never deletes or unlikes anything on your Spotify account"
        if h >= 6:
            cv.text(x + (w - text_width(foot)) // 2, y + h - 1, foot, C.ghost, C.sel)

    def key(self, k, app):
        app.close_modal()
        return True


# ── settings ───────────────────────────────────────────────────────────────

NAMES = {"astral": "Astral", "lava": "Lava", "aurora": "Aurora", "ncs": "NCS",
         "winter": "Winter", "tarkus": "Tarkus", "clock": "Clock", "cornholio": "cornholio",
         "bars": "Bars", "mirror": "Mirror", "kerosene": "Kerosene", "lorn": "Lorn",
         "diffision": "Diffision"}


def shown(value) -> str:
    if value is True:
        return "on"
    if value is False:
        return "off"
    return NAMES.get(value, str(value))


class SettingsPlate:
    """s: everything that changes how cornholio looks, in one quiet list.
    Changes apply at once and are saved."""

    ROWS = [("theme", "theme"), ("translucent", "translucency"), ("scene", "scene"),
            ("visualizer", "NCS visualizer"), ("face", "title font"), ("transition", "title effect"),
            ("loading", "loading screen"), ("autoplay", "autoplay")]
    ABOUT = {
        "astral": "stars drift by, a planet per album · the letters step aside",
        "lava": "a lava lamp · click (left or right) for a new bubble",
        "aurora": "focus's aurora in warm light · a lantern follows the pointer",
        "ncs": "an NCS spectrum over the song's own letters · the pointer leaves a wake",
        "winter": "snow piles into drifts · click to throw some up",
        "tarkus": "focus's turning knot · enter previews",
        "clock": "the time in focus's ASCII digits · enter previews",
        "cornholio": "beavis.art at 78 × 24, butthead.art when larger · enter previews",
        "bars": "NCS's bars · their peaks hang, then fall · v V",
        "mirror": "bass in the middle, mirrored in water · v V",
        "kerosene": "drifting ridges, Unknown Pleasures live · v V",
        "lorn": "Euler's Tonnetz: chords, melody, rhythm · v V",
        "diffision": "Geiss's Reaction Diffusion 3, MilkDrop 2 · v V",
    }

    def __init__(self, app, row=0):
        self.cur = row

    @staticmethod
    def options(key):
        return {"theme": THEME_ORDER, "scene": SCENES, "face": FACE_ORDER, "transition": TRANSITIONS,
                "loading": LOADINGS, "autoplay": [True, False], "visualizer": VISUALIZERS,
                "translucent": [False, True]}[key]

    def hints(self, app):
        return [("↑ ↓", "choose"), ("← →", "change"), ("esc", "close")]

    def about(self, app, key) -> str:
        v = app.cfg.get(key)
        if key in ("scene", "loading", "visualizer"):
            text = self.ABOUT.get(v, "")
            if key == "visualizer" and app.cfg.get("scene") != "ncs":
                text = "shows in the NCS scene · b B changes the scene"
            if key == "scene" and v == "ncs" and app.tap.state in ("missing", "failed"):
                text = "NCS can't hear the music here · see the README"
            return text
        return {"theme": "t T anywhere", "face": "f F in the player", "transition": "e E in the player",
                "autoplay": ("on · similar songs, picked for your taste, carry on"
                             if v else "off · the rest of the song's album plays"),
                "translucent": ("on · the terminal's own opacity shows through"
                                if v else "off · the theme's background, solid")}.get(key, "")

    def draw(self, cv, app, now) -> None:
        n = len(self.ROWS)
        w = 58
        h = n + 7
        x, y, w, h = plate(cv, w, h)
        cv.text(x + 4, y + 1, "settings", C.dim, C.sel)
        for i, (key, label) in enumerate(self.ROWS):
            yy = y + 3 + i
            cur = i == self.cur
            bg = mix(C.sel, C.lift, 0.8) if cur else C.sel
            cv.fill(x + 2, yy, w - 4, 1, bg)
            if cur:
                cv.put(x + 2, yy, "›", C.accent, bg)
            cv.text(x + 4, yy, label, C.dim if cur else C.faint, bg)
            val = shown(app.cfg.get(key))
            vx = x + 22
            if cur:
                cv.put(vx, yy, "‹", mix(C.faint, C.accent, 0.5), bg)
                cv.text(vx + 2, yy, truncate(val, w - 30), C.fg, bg)
                cv.put(vx + 3 + text_width(truncate(val, w - 30)), yy, "›", mix(C.faint, C.accent, 0.5), bg)
                opts = self.options(key)
                if app.cfg.get(key) in opts:                    # where in the list it is
                    k = opts.index(app.cfg.get(key))
                    dots = "".join("•" if j == k else "·" for j in range(len(opts)))
                    if len(opts) <= 12:
                        cv.text(x + w - 4 - len(dots), yy, dots, mix(bg, C.faint, 0.8), bg)
            else:
                cv.text(vx + 2, yy, truncate(val, w - 30), C.dim, bg)
        about = self.about(app, self.ROWS[self.cur][0])
        if about:
            cv.text(x + 4, y + h - 2, truncate(about, w - 8), C.faint, C.sel)

    def change(self, app, step) -> None:
        key, label = self.ROWS[self.cur]
        opts = self.options(key)
        cur = app.cfg.get(key)
        nxt = opts[(opts.index(cur) + step) % len(opts)] if cur in opts else opts[0]
        app.apply_setting(key, nxt)

    def key(self, k, app):
        if k in ("esc", "s", "q", "?"):
            app.close_modal()
        elif k in ("up", "k", "btab"):
            self.cur = (self.cur - 1) % len(self.ROWS)
        elif k in ("down", "j", "tab"):
            self.cur = (self.cur + 1) % len(self.ROWS)
        elif k in ("left", "h"):
            self.change(app, -1)
        elif k in ("right", "l", " "):
            self.change(app, 1)
        elif k == "enter":
            if self.ROWS[self.cur][0] == "loading":
                app.preview_loading(self.cur)
            else:
                self.change(app, 1)
        return True

# ════════════════════════════════════════════════════════════════════════════
#  app: the main loop
# ════════════════════════════════════════════════════════════════════════════

class App:
    def __init__(self, cfg: dict, demo: bool = False, auth: Auth | None = None):
        self.cfg = cfg
        self.demo = demo
        C.__init__(cfg["theme"])
        self.events = queue.Queue()
        self.store = Store()
        self.lib = Library(self.store)
        # the audio engine first: the API thread does not exist yet
        self.player = make_player(cfg, demo)
        self.player.start()
        transport = DemoTransport() if demo else HttpTransport(auth)
        self.transport = transport
        self.api = Api(transport, self.events)
        self.sync = Sync(self.api, self.lib, self.notify)
        self.pb = Playback(self.api, self.notify)
        self.link = None
        if not demo and isinstance(self.player, Soloist) and self.player.proc:
            # Soloist's local socket: instant pause/play and pushed state
            self.link = SoloistLink(self.player.data_dir, self.events)
            self.player.link = self.link
            self.pb.link = self.link
        self.pb.wake = lambda force=False: self.player.wake(time.monotonic(), force)
        self.radio = Radio(self.api, self.lib)
        self.pb.on_track = self._on_track
        self.pb.on_ended = self._autoplay
        self.pb.radio_more = self._radio_more
        self.pb.autoplay_on = lambda: bool(self.cfg.get("autoplay", True))
        self._smart_told = None
        if not demo and self.player.proc:
            try:
                os.nice(max(0, int(cfg.get("cornholio_nice") or 0)))   # the music comes first
            except (OSError, ValueError, TypeError):
                pass
        self.tap = AudioTap(cfg, demo)
        self.scene = Scene(tap=self.tap)
        self.loading = LoadingScreen()
        self.loading_since = None          # the loading screen: shown since, and leaving at
        self.loading_end = None
        self.previewing = None             # a settings row to return to after a preview
        self.loading_held = False          # the cornholio screen waits for a key once ready
        self.loading_done = False
        self.views = {"player": PlayerView(), "library": LibraryView(), "search": SearchView()}
        self.view = "player"
        self.prev_view = "player"
        self.modal = None
        self._note = None
        self.last_key = time.monotonic()
        self.quit = False
        self.last_album = None
        self.started = time.monotonic()
        self._refusals = 0

    # ── small services used by the views
    # Notes stay up for as long as they matter: two seconds for the everyday
    # ones, four for what you'd want to be sure of (likes, unlikes, warnings).
    NOTE_TIME = {"info": 2.0, "important": 4.0, "warn": 4.0}

    def notify(self, text: str, kind: str = "info", dur: float | None = None) -> None:
        base = self.NOTE_TIME.get(kind, 2.0)
        dur = base if dur is None else min(4.0, max(base, dur))
        self._note = (text, kind, time.monotonic(), dur)

    def note_alpha(self, now):
        """The note and how visible it is: in over 0.15 s, out over the last 0.35 s."""
        if not self._note:
            return None, 0.0
        text, kind, t0, dur = self._note
        age = now - t0
        if age > dur:
            self._note = None
            return None, 0.0
        a = min(1.0, age / 0.15) * min(1.0, (dur - age) / 0.35)
        return self._note, max(0.0, a)

    def draw_note_box(self, cv: Canvas, y: int, note, a: float) -> None:
        """A note in a clean rounded box, its text on row y."""
        text, kind = truncate(note[0], cv.w - 8), note[1]
        w = text_width(text) + 4
        x = (cv.w - w) // 2
        edge = {"warn": mix(C.faint, C.warn, 0.6), "important": mix(C.faint, C.accent, 0.55)}.get(
            kind, mix(C.bg, C.faint, 0.95))
        ink = {"warn": C.warn, "important": C.fg}.get(kind, C.dim)
        edge, ink = mix(C.bg, edge, a), mix(C.bg, ink, a)
        for yy, (l, m, r) in ((y - 1, "╭─╮"), (y, "│ │"), (y + 1, "╰─╯")):
            if not 0 <= yy < cv.h:
                continue
            cv.fill(x, yy, w, 1, C.bg)
            cv.put(x, yy, l, edge, C.bg)
            cv.put(x + w - 1, yy, r, edge, C.bg)
            if m == "─":
                for i in range(1, w - 1):
                    cv.put(x + i, yy, "─", edge, C.bg)
        cv.text(x + 2, y, text, ink, C.bg)

    def draw_note(self, cv: Canvas, y: int) -> bool:
        note, a = self.note_alpha(time.monotonic())
        if not note:
            return False
        self.draw_note_box(cv, y, note, a)
        return True

    def idle_label(self) -> str:
        st = self.player.state
        if self.demo and not self.pb.cornholio_device:
            return "waking the player"
        said = None if self.demo else self.player.idle_label()
        if said:
            return said
        if st in ("starting", "pairing") and not self.pb.cornholio_device:
            return "waking the player"
        if self.view != "player":
            return "nothing playing · enter on a song plays it"
        return "nothing playing · tab opens your library"

    def show(self, name: str) -> None:
        if name != self.view:
            self.prev_view = self.view
            self.view = name

    def back(self) -> None:
        self.view = self.prev_view if self.prev_view != self.view else "player"
        if self.view == "search":
            self.view = "library"

    def open_modal(self, m) -> None:
        self.modal = m

    def close_modal(self) -> None:
        self.modal = None

    def playing_list_key(self):
        ses = self.pb.session
        if ses and self.pb.s.item:
            return ses["key"]
        ctx = self.pb.s.context
        if ctx and ctx.startswith("spotify:playlist:"):
            return "pl:" + ctx.split(":")[2]
        return None

    def playing_playlist(self):
        """The id of the playlist that's playing (what Spotify says, else what
        cornholio started), or None."""
        ses = self.pb.session
        mine = re.match(r"(?:pl:|spotify:playlist:)([A-Za-z0-9]+)$", ses["key"]) if ses else None
        said = re.search(r"playlist:([A-Za-z0-9]+)", self.pb.s.context or "")
        if mine and (not said or time.monotonic() - self.pb.last_user < 8):
            return mine.group(1)                 # just started here: Spotify may not have caught up
        return (said or mine).group(1) if (said or mine) else None

    def whose_playlist(self) -> None:
        """w: from the playlist that's playing to the page of the person who made it."""
        pid = self.playing_playlist()
        if not pid:
            self.notify("w works while a playlist is playing")
            return
        p = self.lib.playlists.get(pid)
        if p and p["owned"] and not p.get("collaborative"):
            self.notify(f"“{truncate(p['name'], 30)}” is your own playlist")
            return
        sv = self.views["search"]
        sv.edit.text = f"spotify:playlist:{pid}"
        sv.edit.pos = len(sv.edit.text)
        self.show("search")
        if p and p.get("owner_id"):                # known already: no request needed
            sv.query = sv.edit.text
            sv.edit.text, sv.edit.pos = "", 0      # a link isn't something to edit: the bar empties
            sv.gen += 1
            sv.results = {k: [] for k, _ in sv.SECTIONS}
            sv.album = None
            sv.open_person(self, {"id": p["owner_id"], "name": p["owner"]}, pin=p)
            return
        sv.want_owner = True                       # a followed playlist: its owner, not the library
        sv.run(self)
        sv.typing = False

    def jump_to_playing(self) -> None:
        s = self.pb.s
        if not s.item:
            self.notify("nothing is playing")
            return
        key = self.playing_list_key()
        lv = self.views["library"]
        if key and (key == "liked" or key[3:] in self.lib.playlists):
            self.show("library")
            lv.reveal(self, key, s.item["uri"])
        else:
            self.notify("playing from outside your library")

    # ── adding and creating (the only changes cornholio makes)
    def add_to_playlist(self, pid: str, tracks) -> None:
        name = self.lib.playlists.get(pid, {}).get("name", "playlist")
        self.api.submit(P_USER, "POST", f"/playlists/{pid}/items",
                        body={"uris": [t["uri"] for t in tracks]},
                        tag=("added", pid, tracks, name))

    def create_playlist(self, name: str, tracks) -> None:
        self.api.submit(P_USER, "POST", "/me/playlists",
                        body={"name": name, "public": False, "description": ""},
                        tag=("created", name, tracks))

    # Spotify's "save to library" takes the URIs in the address (?uris=a,b),
    # forty at most; a JSON body is refused with a 400
    def save_to_library(self, tracks) -> None:
        uris = [t["uri"] for t in tracks if (t.get("uri") or "").startswith("spotify:")]
        if not uris:
            self.notify("that can't be saved", "warn")
            return
        for i in range(0, len(uris), 40):
            part = uris[i:i + 40]
            self.api.submit(P_USER, "PUT", "/me/library", {"uris": ",".join(part)},
                            tag=("saved", [t for t in tracks if t["uri"] in part], None))

    # ── the queue, autoplay and the radio
    def queue_track(self, t) -> None:
        if not t or not (t.get("uri") or "").startswith("spotify:track:"):
            self.notify("only songs can be queued")
            return
        self.notify(self.pb.enqueue(dict(t)))

    def _on_track(self, item, context, smart, queued=False) -> None:
        """Every song that starts playing, wherever it was started."""
        self.radio.heard(item["uri"])
        if not queued:                         # a song you queued isn't part of the playlist
            self.capture_mirror(item, context, smart)

    def _radio_more(self, seed, exclude, ses) -> None:
        """The last song of what you started has begun: find what comes after
        it. Autoplay on: the radio first, and if it finds nothing, the rest of
        the song's album. Autoplay off: the rest of the song's album."""
        if not self.cfg.get("autoplay", True):
            self._album_rest(seed, exclude, ses)
            return

        def done(picks):
            if picks:
                self.pb.stash(ses, picks)
            else:
                self._album_rest(seed, exclude, ses)
        self.radio.build(seed, done, exclude)

    def _album_rest(self, seed, exclude, ses) -> None:
        def cb(rest):
            if rest and ses is self.pb.session:
                self.notify(f"autoplay · the rest of {truncate(seed.get('album') or 'the album', 30)}")
            self.pb.stash(ses, rest)
        self._album_then(seed, exclude, cb)

    def _on_album_rest(self, cb, seed, exclude, status, data) -> None:
        rest = []
        if status == 200 and data:
            tracks = []
            for o in data.get("items") or []:
                t = parse_track(o)
                if t:
                    t["album"], t["album_uri"] = seed.get("album", ""), seed.get("album_uri")
                    tracks.append(t)
            uris = [t["uri"] for t in tracks]
            if seed["uri"] in uris:
                rest = [t for t in tracks[uris.index(seed["uri"]) + 1:] if t["uri"] not in exclude]
        cb(rest[:20])

    def _autoplay(self, last) -> None:
        """What cornholio started has run out and the player stopped (Spotify
        didn't carry on by itself). Whatever was already found plays at once;
        otherwise autoplay on asks the radio (then the album), autoplay off
        plays the rest of the album the song is on."""
        ses = self.pb.session
        on = bool(self.cfg.get("autoplay", True))

        def play(picks, quiet=False):
            if self.pb.s.is_playing:               # something started meanwhile: leave it
                return
            if not picks:
                if not quiet:
                    self.notify("autoplay found nothing new to play")
                return
            self.pb.play_tracks("radio", picks, 0, radio=True)

        if ses and ses.get("pending") and not ses.get("handed"):
            ses["handed"] = True
            play(ses["pending"])
            return
        if not on:                                 # off: just the rest of the album
            def rest(picks):
                if picks:
                    self.notify(f"the rest of {truncate(last.get('album') or 'the album', 30)}")
                play(picks, quiet=True)
            self._album_then(last, set(), rest)
            return
        self.notify(f"autoplay · songs like “{truncate(last.get('name', ''), 28)}”")

        def go(picks, last=last):
            if picks:
                play(picks)
            else:                                  # no radio: the rest of the album
                self._album_then(last, set(), play)
        self.radio.build(last, go)

    def _album_then(self, seed, exclude, cb) -> None:
        au = seed.get("album_uri") or ""
        if not au.startswith("spotify:album:"):
            cb([])
            return
        self.api.submit(P_USER, "GET", f"/albums/{au.split(':')[2]}/tracks", {"limit": 50},
                        tag=("albumrest", cb, seed, set(exclude)))

    # ── mirrors of playlists you follow
    def _followed(self, pid):
        p = self.lib.playlists.get(pid)
        return p if p and not p["owned"] else None

    def capture_mirror(self, item, context, smart) -> None:
        """A song playing from a playlist you follow joins that playlist's
        mirror. Not with smart shuffle on: it mixes in songs from elsewhere.

        The playlist comes from what's playing (Soloist always says; Spotify's
        API often leaves it out for playlists you don't own), else from what
        cornholio itself started."""
        ses = self.pb.session
        how = self.pb.settle(item, time.monotonic())
        if how == "skip":                      # still the song from before the switch
            return
        if how == "session":                   # just switched: the list cornholio started decides
            m = re.match(r"(?:pl:|spotify:playlist:)([A-Za-z0-9]+)$", ses["key"])
        else:
            m = re.search(r"playlist:([A-Za-z0-9]+)", context or "")
            if not m and not context:
                m = re.search(r"^spotify:playlist:([A-Za-z0-9]+)$", ses["key"]) if ses else None
        if not m:
            return
        pid = m.group(1)
        if not self._followed(pid):
            return
        if smart:
            if self._smart_told != pid:
                self._smart_told = pid
                self.notify("smart shuffle is on · it mixes in other songs, so the mirror waits",
                            "important")
            return
        self.lib.mirror_add(pid, item)

    def toggle_mirror(self) -> None:
        """A: swaps between Spotify's own playlist (shuffled, live) and the
        mirror cornholio wrote down, staying on the same song where it can."""
        pb, s = self.pb, self.pb.s
        ses = pb.session
        now = time.monotonic()
        pos = s.progress(now) if s.item else 0
        # playing the mirror → back to Spotify's live playlist
        if ses and ses["key"].startswith("pl:") and self._followed(ses["key"][3:]):
            pid = ses["key"][3:]
            name = self.lib.playlists[pid]["name"]
            pb.play_context(f"spotify:playlist:{pid}", s.item["uri"] if s.item else None,
                            preview=s.item, position_ms=pos if s.item else 0)
            self.notify(f"{name} · Spotify's own, live · A swaps back")
            return
        # playing the live playlist → the mirror, same song, same moment
        live = None
        for ctx in (s.context, ses["key"] if ses else None):
            if ctx and ctx.startswith("spotify:playlist:") and self._followed(ctx.split(":")[2]):
                live = ctx.split(":")[2]
                break
        pid, start_uri = live, (s.item["uri"] if live and s.item else None)
        if pid is None and self.view == "library":
            lv = self.views["library"]
            tl = lv.current_list(self)
            if tl is not None and tl.kind == "playlist" and self._followed(tl.key[3:]):
                pid = tl.key[3:]
                t = tl.by_key.get(lv.right.key) if lv.focus == "right" else None
                start_uri = t["uri"] if t else None
        if pid is None:
            self.notify("A swaps a playlist you follow between Spotify's live one and its mirror")
            return
        tl = self.lib.list_for(pid)
        self.lib.load_mirror(tl)
        rows = self.lib.visible_tracks(tl, False, "")
        name = self.lib.playlists[pid]["name"]
        if not rows:
            self.notify(f"nothing heard from {name} yet · play it and it fills up")
            return
        uris = [t["uri"] for t in rows]
        idx = uris.index(start_uri) if start_uri in uris else 0
        keep = live is not None and start_uri in uris
        pb.play_tracks(tl.key, rows, idx, position_ms=pos if keep else 0)
        self.notify(f"{name} · as written down here, {len(rows)} songs · A swaps back")

    # ── the song a key acts on: under the cursor in a list, else the one playing
    def target_song(self):
        v = self.views[self.view]
        if self.view == "library" and v.focus == "right":
            tl = v.current_list(self)
            t = tl.by_key.get(v.right.key) if tl else None
            if t:
                return t
        elif self.view == "search":
            sel = v.selected()
            if sel and sel[0] == "tracks":
                return sel[1]
        t = self.pb.s.item
        return t if t and (t.get("uri") or "").startswith("spotify:track:") else None

    def _liked_state(self, t):
        """True / False when Liked Songs is loaded, None when it isn't yet."""
        liked = self.lib.liked
        if liked.status != "ready":
            return None
        return any(x["uri"] == t["uri"] for x in liked.tracks)

    def like(self, t) -> None:
        if not t:
            self.notify("pick a song first, or play one")
            return
        name = truncate(t["name"], 32)
        key = t["uri"] + "#0"
        if self.store.is_hidden_track("liked", key):      # unliked here before: it comes back
            self.store.toggle_hidden_track("liked", key)
            self.notify(f"♥ “{name}” is back in your Liked Songs", "important")
            return
        if self._liked_state(t):
            self.notify(f"♥ “{name}” is already in your Liked Songs", "important")
            return
        self.save_to_library([dict(t)])

    def unlike(self, t) -> None:
        """Unliking happens here only: the song leaves your Liked Songs in
        cornholio and stays saved on Spotify. l brings it back."""
        if not t:
            self.notify("pick a song first, or play one")
            return
        name = truncate(t["name"], 32)
        key = t["uri"] + "#0"
        if self.store.is_hidden_track("liked", key):
            self.notify(f"“{name}” is already unliked here · l likes it again", "important")
            return
        if self._liked_state(t) is False:
            self.notify(f"“{name}” isn't in your Liked Songs", "important")
            return
        self.store.toggle_hidden_track("liked", key)
        self.notify(f"unliked “{name}” here · Spotify keeps it · l brings it back", "important")

    def like_playing(self) -> None:
        self.like(self.pb.s.item)

    def add_song(self, t) -> None:
        if not t:
            self.notify("pick a song first, or play one")
            return
        self.open_modal(AddPicker(self, [dict(t)]))

    def add_playing(self) -> None:
        self.add_song(self.pb.s.item)

    def save_uri(self, uri: str, name: str) -> None:
        self.api.submit(P_USER, "PUT", "/me/library", {"uris": uri}, tag=("saved", [], name))

    # ── settings
    def set_cfg(self, key, value) -> None:
        self.cfg[key] = value
        save_config(self.cfg)

    def cycle(self, key, order, label, step: int = 1) -> None:
        """Lowercase key steps forward, uppercase steps back."""
        cur = self.cfg.get(key)
        nxt = order[(order.index(cur) + step) % len(order)] if cur in order else order[0]
        self.apply_setting(key, nxt)
        self.notify(f"{label}: {shown(nxt)}")

    def apply_setting(self, key, value) -> None:
        if key == "theme":
            C.switch(value, time.monotonic())
        self.set_cfg(key, value)
        if key == "transition":
            self.views["player"].replay()

    def preview_loading(self, row) -> None:
        """Settings → loading screen → enter: show it until a key is pressed."""
        self.close_modal()
        self.previewing = row
        self.loading.reset()

    # ── events from the API thread
    def handle_event(self, ev) -> None:
        if ev[0] == "local":
            e = ev[1]
            if e.get("type") == "auth_state" and e.get("logged_in") and \
                    hasattr(self.player, "on_auth"):
                self.player.on_auth(True)
            self.pb.on_local(e)
            return
        if ev[0] == "ratelimited":
            self.notify(f"Spotify asked cornholio to slow down · resuming in {int(ev[1])} s", "warn")
            return
        _, tag, status, data, job = ev
        kind = tag[0] if tag else None
        if kind == "me":
            self.sync.on_me(status, data)
        elif kind == "pls":
            self.sync.on_playlists(tag[1], status, data, job)
        elif kind == "items":
            self.sync.on_items(tag[1], tag[2], status, data, job)
        elif kind == "liked_head":
            self.sync.on_liked_head(tag[1], status, data)
        elif kind == "player":
            if self.pb.pending_seek or self.pb.pending_vol:
                return
            self.pb.on_player(tag[1], status, data)
        elif kind == "devices":
            self.pb.on_devices(status, data)
        elif kind == "radio":
            self.radio.on_result(tag, status, data)
        elif kind == "albumrest":
            self._on_album_rest(tag[1], tag[2], tag[3], status, data)
        elif kind == "cmd":
            self.pb.on_cmd(tag[1], status, data)
        elif kind == "search":
            self.views["search"].on_result(self, tag[1], tag[2], status, data)
        elif kind == "added":
            pid, tracks, name = tag[1], tag[2], tag[3]
            if status in (200, 201) and data:
                self.sync.added(pid, tracks, data.get("snapshot_id"))
                what = tracks[0]["name"] if len(tracks) == 1 else f"{len(tracks)} songs"
                self.notify(f"added “{truncate(what, 28)}” to {name}")
            else:
                self.notify(self._why(status, data, f"couldn't add to {name}"), "warn")
        elif kind == "created":
            name, tracks = tag[1], tag[2]
            if status in (200, 201) and data:
                p = Library.parse_playlist(data, self.lib.me)
                if p:
                    p["owned"] = True
                    if p["total"] is None:
                        p["total"] = 0
                    self.lib.add_playlist(p)
                    tl = self.lib.list_for(p["id"])
                    tl.set_tracks([])
                    tl.snapshot = p["snapshot"]
                    tl.status = "ready"
                    self.notify(f"created {name}")
                    if tracks:
                        self.add_to_playlist(p["id"], tracks)
            else:
                self.notify(self._why(status, data, "couldn't create the playlist"), "warn")
        elif kind == "saved":
            tracks, name = tag[1], tag[2]
            if status in (200, 201, 204):
                self.sync.liked_added(tracks)
                if tracks and not name:
                    what = tracks[0]["name"] if len(tracks) == 1 else f"{len(tracks)} songs"
                    self.notify(f"♥ liked “{truncate(what, 32)}”", "important")
                else:
                    self.notify(f"saved “{truncate(name or '', 32)}” to your library", "important")
            else:
                self.notify(self._why(status, data, "couldn't save"), "warn")

    @staticmethod
    def _why(status, data, fallback) -> str:
        if status == -1:
            return "blocked by cornholio's safety list"
        if status == 0:
            return fallback + " (offline)"
        if status == 403:
            return fallback + " (Spotify said no)"
        if status == 401:
            return "your login expired · run  cornholio login"
        return f"{fallback} ({status})"

    # ── keys
    def handle_paste(self, k) -> None:
        """Pasted text goes into whatever is being typed. A pasted Spotify link
        anywhere else opens it in search; other pasted text is never taken as keys."""
        sv = self.views["search"]
        if self.modal:
            if hasattr(self.modal, "edit"):
                self.modal.key(k, self)
            return
        if self.view == "search" and sv.typing:
            sv.key(k, self)
            if parse_spotify_link(sv.edit.text):      # a link opens straight away
                sv.run(self)
                sv.typing = False
            return
        if parse_spotify_link(k.text):
            sv.edit.text = " ".join(k.text.split())
            sv.edit.pos = len(sv.edit.text)
            self.show("search")
            sv.run(self)
            sv.typing = False

    def dismiss_loading(self, k) -> bool:
        """Any key or click, once the player is ready, sends the cornholio
        screen away (that key does nothing else)."""
        if not (self.loading_held and self.loading_since is not None and self.previewing is None):
            return False
        if isinstance(k, Mouse) and (not k.pressed or (k.button & 32)):
            return False                       # pointer moves don't count
        if self.waking():
            return False
        if k == "ctrl-c":
            return False
        self.loading_held = False
        self.loading_end = time.monotonic()
        return True

    def handle_key(self, k) -> None:
        if self.dismiss_loading(k):
            return
        if isinstance(k, Paste):
            self.handle_paste(k)
            return
        if isinstance(k, Mouse):
            # The mouse only paints light in the player; it never selects or controls.
            # A click adds to some scenes: a lava bubble, a throw of snow.
            if self.view == "player" and not self.modal and not self.loading_on():
                b = k.button
                if b >= 64:                       # the wheel
                    return
                now = time.monotonic()
                pv = self.views["player"]
                scene = self.cfg.get("scene", "astral")
                mode = Scene.CURSOR.get(scene, "repel")
                step = pv.cursor.move(k.x, k.y, now, mode)
                if scene == "lava":
                    self.scene.lava.moved(k.x, k.y)
                if k.pressed and not (b & 32) and (b & 3) in (0, 2):
                    self.scene.click(k.x, k.y, scene, fx_level(self.scene.w, self.scene.h))
                self.scene.touch(k.x, k.y, now)
            return
        self.last_key = time.monotonic()
        if k == "ctrl-c":
            self.quit = True
            return
        if self.previewing is not None:        # any key ends a preview, back to settings
            row, self.previewing = self.previewing, None
            self.open_modal(SettingsPlate(self, row))
            return
        if self.modal:
            self.modal.key(k, self)
            return
        v = self.views[self.view]
        typing = (self.view == "search" and v.typing) or \
                 (self.view == "library" and (v.editing is not None))
        moving = self.view == "library" and v.move is not None
        if typing or moving:
            if v.key(k, self):
                return
            if k == "ctrl-c":
                self.quit = True
            return
        if v.key(k, self):
            return
        self.global_key(k)

    def global_key(self, k) -> None:
        pb = self.pb
        if k == "s":
            self.open_modal(SettingsPlate(self))
        elif k == "l":
            self.like(self.target_song())
        elif k == "L":
            self.unlike(self.target_song())
        elif k == "a":
            self.add_song(self.target_song())
        elif k == "q":
            self.notify("ctrl-c quits · q queues a song in the library and search")
        elif k == "A":
            self.toggle_mirror()
        elif k == "tab":
            self.show("library" if self.view != "library" else "player")
        elif k == "btab":
            self.show("player")
        elif k == "/":
            sv = self.views["search"]
            sv.typing = True
            sv.album = None
            self.show("search")
        elif k == "?":
            self.open_modal(HelpPlate())
        elif k == " ":
            pb.toggle()
        elif k == "n":
            pb.next()
        elif k == "p":
            pb.prev()
        elif k == "[":
            pb.seek(-10)
        elif k == "]":
            pb.seek(10)
        elif k == "-":
            pb.volume(-5)
        elif k in ("+", "="):
            pb.volume(5)
        elif k == "z":
            pb.toggle_shuffle()
        elif k == "r":
            pb.cycle_repeat()
        elif k == "o":
            self.jump_to_playing()
        elif k == "w":
            self.whose_playlist()
        elif k == "d":
            pb.play_here()
        elif k in ("t", "T"):
            self.cycle("theme", THEME_ORDER, "theme", 1 if k == "t" else -1)
        elif k in ("b", "B"):
            self.cycle("scene", SCENES, "scene", 1 if k == "b" else -1)
        elif k == "esc" and self.view != "player":
            self.show("player")

    # ── drawing
    @staticmethod
    def quiet_row(cv: Canvas, y: int, alpha: float) -> None:
        """Diffision reaches the last row: while the hints show, it sinks toward the
        background there, as much as they show, so they read."""
        k = 0.88 * alpha
        a, b = y * cv.w, (y + 1) * cv.w
        cv.fg[a:b] = [mix(c, C.bg, k) for c in cv.fg[a:b]]
        cv.bg[a:b] = [mix(c, C.bg, k) for c in cv.bg[a:b]]

    def draw_header(self, cv: Canvas) -> None:
        W = cv.w
        cv.text(2, 0, "cornholio", C.faint)
        tabs = [("player", "player"), ("library", "library"), ("search", "search")]
        total = sum(text_width(t) for _, t in tabs) + 4 * (len(tabs) - 1)
        if W >= total + 34:
            x = (W - total) // 2
            for name, label in tabs:
                c = C.dim if name == self.view else mix(C.bg, C.faint, 0.75)
                x = cv.text(x, 0, label, c) + 4
        s = self.pb.s
        st = self.player.state
        if self.pb.local() or (self.pb.cornholio_device and
                               (not s.device_id or s.device_id == self.pb.cornholio_device)):
            dot, label, dc = "●", self.cfg.get("device_name", "cornholio"), mix(C.dim, C.accent, 0.5)
        elif s.device_id and s.device_name:
            dot, label, dc = "●", "on " + s.device_name, C.faint
        elif st == "starting":
            dot, label, dc = "◌", "waking", C.faint
        elif st in ("missing", "needs-key", "needs-login", "pairing", "refused", "expired",
                    "crashed"):
            dot, label, dc = "○", self.player.header_label(), mix(C.faint, C.warn, 0.5)
        else:
            dot, label, dc = "○", "no player", C.faint
        if self.demo:
            label += " · demo"
        x = W - 2 - text_width(label) - 2
        cv.put(x, 0, dot, dc)
        cv.text(x + 2, 0, label, C.faint)

    # ── the loading screen
    WAKE_GIVE_UP = 30.0                    # the loading screen never outstays this

    def waking(self, now=None) -> bool:
        """The player is on its way but not ready: it is ready once Spotify
        lists it (the moment "the player is awake" is said and held commands
        go out), not merely when its process or socket is up."""
        now = time.monotonic() if now is None else now
        if self.loading_since is not None and now - self.loading_since > self.WAKE_GIVE_UP:
            return False
        if self.pb.cornholio_device:
            return False
        if self.demo:
            return True
        return self.player.state in ("starting", "running")

    def loading_alpha(self, now) -> float:
        """1 while the player wakes (for at least a moment once shown), then a
        short dissolve into the player; 0 when there is nothing to show."""
        if self.previewing is not None:
            return 1.0
        if self.loading_since is None and not self.loading_done and self.waking(now):
            self.loading_since, self.loading_end = now, None
            self.loading_held = self.cfg.get("loading") == "cornholio"
        if self.loading_since is None:
            return 0.0
        if self.waking(now):
            return 1.0
        if self.loading_held:                  # cornholio's screen stays until you press a key
            return 1.0
        if self.loading_end is None:
            self.loading_end = max(now, self.loading_since + 1.0)
        if now < self.loading_end:
            return 1.0
        k = (now - self.loading_end) / 0.6
        if k >= 1:
            self.loading_since = self.loading_end = None
            self.loading_done = True           # once a session: never back after the player woke
            self.loading.reset()
            return 0.0
        return 1 - k

    def loading_on(self) -> bool:
        return self.view == "player" and (self.previewing is not None or self.loading_since is not None)

    def draw(self, cv: Canvas, now: float) -> None:
        W, H = cv.w, cv.h
        cv.reset(C.bg)
        if W < 24 or H < 6:                     # too small for anything else: the time
            text = time.strftime("%H:%M")
            rows = clock_rows(text, W, H)
            if rows:
                y0 = (H - len(rows)) // 2
                for y, r in enumerate(rows):
                    cv.text((W - len(r)) // 2, y0 + y, r, C.fg)
            else:
                t = plain_time(text, W)
                cv.text(max(0, (W - len(t)) // 2), H // 2, t, C.fg, bold=True)
            return
        la = self.loading_alpha(now) if self.view == "player" else 0.0
        label = None if self.previewing is not None else self.idle_label()
        if la >= 1 and self.loading_held and self.previewing is None and not self.waking(now):
            label = "the player is awake · press any key"
        if la >= 1:
            self.loading.draw(cv, now, self.cfg.get("loading", "tarkus"), label)
            if self.modal:
                self.modal.draw(cv, self, now)
            return
        mode = self.cfg.get("scene", "astral")
        dim = 0.0 if self.view == "player" else 0.62
        if self.modal and self.view == "player":
            dim = 0.45
        pv = self.views["player"]
        ground = self.view == "player" and not self.modal
        pv.layout(self, W, H)
        if self.view == "player":       # elsewhere the lists cover the whole scene
            pv.cursor.advance(now, Scene.CURSOR.get(mode, "repel"), W, H)
            ko = pv.keep_out(W, H)
            clear = pv.clear_zone(W, H)
            ctx = None
            if mode in ("aurora", "ncs", "lava"):
                item = self.pb.s.item
                hx0, hx1 = pv.hero_box
                ctx = types.SimpleNamespace(
                    cursor=pv.cursor, plan=pv.plan, playing=bool(self.pb.s.is_playing),
                    title=item["name"] if item else "", skip_rows=set(),
                    ink_y=pv.plan.top + pv.hero.ink_top,
                    visual=self.cfg.get("visualizer", "bars"),
                    hero=(hx0, hx1, pv.plan.top + pv.hero.ink_top, pv.plan.top + pv.plan.hero_h),
                    mask=zone_grid(clear, W, H, pv.zone_key(W, H)))
            self.scene.draw(cv, now, mode, dim, ground=ground, keep_out=ko, clear=clear, ctx=ctx)
        v = self.views[self.view]
        if not (self.modal and self.view == "player"):
            v.draw(cv, self, now)
        self.draw_header(cv)
        if self.modal:
            self.modal.draw(cv, self, now)
        # footer: a note in its box takes over the hint line, except under
        # the player's own note row
        hints = (self.modal or v).hints(self)
        note, a = self.note_alpha(now)
        p = pv.plan
        in_row = self.view == "player" and not self.modal and p is not None and \
            p.note_y is not None and not p.compact
        picture = self.view == "player" and p is not None and p.vis_top is not None
        if note and not in_row:
            self.draw_note_box(cv, H - 2, note, a)
        elif self.view != "player" or self.modal:
            if picture:
                self.quiet_row(cv, H - 1, 1.0)
            draw_hints(cv, H - 1, hints)
        elif not (note and p.note_y + 1 >= H - 1):
            idle = now - self.last_key
            alpha = 1.0 if idle < 12 else max(0.0, 1 - (idle - 12) / 2.5)
            if picture and alpha > 0.01:
                self.quiet_row(cv, H - 1, alpha)
            draw_hints(cv, H - 1, hints, alpha)
        if 0 < la < 1:                          # the loading screen dissolving into the player
            self.loading.draw(cv, now, self.cfg.get("loading", "tarkus"), label, alpha=la)

    # ── main loop
    def tick(self, now: float, dt: float) -> None:
        C.update(now)
        self.pb.tick(now, self.cfg.get("device_name", "cornholio"),
                     want_device=self.player.wants_device)
        msg = self.player.check(now)
        if msg:
            self.notify(msg, "warn")
        self.tap.tick(now, bool(self.pb.s.is_playing), dt)
        if self.tap.note:
            self.notify(self.tap.note, "warn")
            self.tap.note = None
        if self.player.refusals != self._refusals:
            self._refusals = self.player.refusals
            self.pb.halt()           # don't let it skip through the whole list
        pb = self.pb
        if self.player.state == "starting" and not pb.cornholio_device and pb.s.known \
                and not pb.s.is_playing:
            self.player.wake(now)    # nothing plays anywhere: safe to step forward
        if self.player.state in ("starting", "pairing") and (self.pb.cornholio_device or pb.local()):
            self.player.state = "running"
            if hasattr(self.player, "on_found"):
                self.player.on_found()
        self.store.save()
        self.radio.tick(now)
        self.lib.save_mirrors()
        item = self.pb.s.item
        album = item and (item.get("album_uri") or item.get("album"))
        if album and album != self.last_album:
            self.last_album = album
            self.scene.on_album(album, now)
        pv = self.views["player"]
        cap = pv.snow_cap(self.scene.h) if pv.plan else 0
        self.scene.update(dt, now, self.cfg.get("scene", "astral"),
                          bool(self.pb.s.is_playing), cap, pv.hero_box)

    def frame_rate(self, fps: int, busy: float) -> int:
        """Frames a second: the configured rate; while Lorn is on screen its
        own (60, "lorn_fps"), or as many as this computer makes in 70% of its
        time, never fewer than the configured rate. Diffision's frames cost the
        most (a whole window of colour): in a very large window they ease off,
        never under 15, so cornholio keeps to half a core (its MilkDrop frames
        run on, sixty a second, however few are drawn)."""
        ncs = self.view == "player" and self.cfg.get("scene") == "ncs"
        if ncs and self.cfg.get("visualizer") == "diffision":
            return max(min(fps, 15), min(fps, int(0.5 / busy))) if busy > 0 else fps
        lorn = ncs and not self.modal and self.cfg.get("visualizer") == "lorn"
        want = self.cfg.get("lorn_fps", 60)
        if not lorn or want <= fps:
            return fps
        return max(fps, min(want, int(0.7 / busy))) if busy > 0 else want

    def run(self) -> None:
        term = Terminal()

        def on_signal(sig, frame):
            self.quit = True

        signal.signal(signal.SIGTERM, on_signal)
        signal.signal(signal.SIGHUP, on_signal)
        try:
            with term:
                inp = Input(term.ifd)
                ren = Renderer(term)
                W, H = term.size()
                cv = Canvas(W, H, C.bg)
                self.scene.resize(W, H)
                self.sync.start()
                fps = max(5, min(60, int(self.cfg.get("fps", 30))))
                last = time.monotonic()
                next_frame = last
                busy = 0.0                        # how long a frame takes to make, smoothed
                while not self.quit:
                    keys = inp.read(max(0.0, next_frame - time.monotonic()))
                    for k in keys:
                        self.handle_key(k)
                        if self.quit:
                            break
                    for _ in range(300):
                        try:
                            ev = self.events.get_nowait()
                        except queue.Empty:
                            break
                        try:
                            self.handle_event(ev)
                        except Exception:
                            log("event error", ev[:2], traceback.format_exc())
                    now = time.monotonic()
                    if now < next_frame and not keys:
                        continue
                    dt = min(0.1, now - last)
                    last = now
                    w, h = term.size()
                    if (w, h) != (cv.w, cv.h):
                        cv.resize(w, h, C.bg)
                        self.scene.resize(w, h)
                        ren.invalidate()
                    self.tick(now, dt)
                    self.draw(cv, now)
                    ren.translucent = bool(self.cfg.get("translucent"))
                    ren.flush(cv)
                    busy += (time.monotonic() - now - busy) * 0.1
                    next_frame = now + 1.0 / self.frame_rate(fps, busy)
        finally:
            term.restore()
            self.api.shutdown()
            self.tap.stop()
            if self.link:
                self.link.close()
            self.player.stop()
            self.store.hold = False
            self.store.save(force=True)
            self.lib.save_mirrors(force=True)


# ════════════════════════════════════════════════════════════════════════════
#  entry point
# ════════════════════════════════════════════════════════════════════════════

def load_config() -> dict:
    path = CONFIG_DIR / "config.json"
    user = read_json(path, None)
    cfg = dict(DEFAULTS)
    if isinstance(user, dict):
        if "lull_nice" in user and "cornholio_nice" not in user:
            user["cornholio_nice"] = user["lull_nice"]
        if user.get("device_name") == "lull":     # the old default name follows the rename
            user["device_name"] = "cornholio"
        if "scene" not in user and "background" in user:   # background + cursor became the scene
            user["scene"] = "winter" if user.get("background") == "snow" else "astral"
        if user.get("scene") == "murmur":                    # murmur is NCS now
            user["scene"] = "ncs"
        if user.get("visualizer") in ("ridges", "rain"):     # renamed: Kerosene and Lorn
            user["visualizer"] = {"ridges": "kerosene", "rain": "lorn"}[user["visualizer"]]
            save_config(dict(DEFAULTS, **{k: v for k, v in user.items() if k in DEFAULTS}))
        cfg.update({k: v for k, v in user.items() if k in DEFAULTS})
        if set(user) - set(DEFAULTS) or user.get("device_name") != cfg.get("device_name"):
            save_config(cfg)
    else:
        save_config(cfg)          # write the defaults once, so they're easy to find and edit
    if cfg["theme"] not in THEMES:
        cfg["theme"] = THEME_ORDER[0]
    old_face = cfg.get("face")
    cfg["face"] = {"fine": "obeliks", "line": "obeliks", "monument": "obeliks", "poster": "obeliks",
                   "obelisk": "obeliks"}.get(old_face, old_face)
    if cfg["face"] not in FACE_ORDER:
        cfg["face"] = "smooth"
    for key, order in (("transition", TRANSITIONS), ("scene", SCENES), ("loading", LOADINGS),
                       ("visualizer", VISUALIZERS)):
        if cfg.get(key) not in order:
            cfg[key] = DEFAULTS[key]
    try:
        cfg["lorn_fps"] = max(5, min(60, int(cfg.get("lorn_fps", 60))))
    except (TypeError, ValueError):
        cfg["lorn_fps"] = DEFAULTS["lorn_fps"]
    cfg["translucent"] = cfg.get("translucent") in (True, 1, "on", "true", "yes")
    if cfg["face"] != old_face and isinstance(user, dict):
        save_config(cfg)
    return cfg


def save_config(cfg: dict) -> None:
    try:
        CONFIG_DIR.mkdir(parents=True, exist_ok=True)
        p = CONFIG_DIR / "config.json"
        p.write_text(json.dumps(cfg, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    except OSError as e:
        log("config write failed", e)


def main(argv=None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    if any(a in ("-h", "--help", "help") for a in args):
        print(__doc__)
        return 0
    if "--version" in args:
        print(f"cornholio {VERSION}")
        return 0
    demo = "--demo" in args
    moved = migrate_old_name()
    if moved:
        print("Renamed from lull: your settings, logins and library moved over.")
    if demo:
        set_demo_dirs(_xdg("XDG_CACHE_HOME", ".cache") / APP / "demo")
    cfg = load_config()
    if "player-login" in args:
        return make_player(cfg).interactive_login()
    auth = None
    if not demo:
        auth = Auth(cfg.get("client_id") or CLIENT_ID)
        try:
            if "login" in args:
                auth.login()
                return 0
            if not auth.logged_in:
                print("Welcome to cornholio. First, a one-time Spotify login.\n")
                auth.login()
            elif auth.missing_scopes():
                print("cornholio needs a few more permissions than your saved login has "
                      f"({', '.join(auth.missing_scopes())}).\n")
                auth.login()
        except AuthError as e:
            print(f"Login failed: {e}")
            return 1
        except KeyboardInterrupt:
            return 130
    if not sys.stdin.isatty() or not sys.stdout.isatty():
        print("cornholio needs a real terminal.")
        return 1
    app = App(cfg, demo, auth)
    try:
        app.run()
    except TerminalGone:
        return 0
    except Exception:
        log("crash", traceback.format_exc())
        print(f"cornholio stopped unexpectedly. Details: {LOG_FILE}")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
